#include "loots/loots.h"

#include <algorithm>
#include <cstring>
#include <map>
#include <utility>

#include "jigsaw_templates.hpp"
#include "loots/loot.h"
#include "loots/rng.h"
#include "loots/transform.h"
#include "pieces_c.h"

// Ancient-city chest evaluation.
//
// The piece graph (which template lands where) is generated by the host: the
// host injects an AncientCityLayoutFn that runs the same 26.3 layout engine as
// the geode finder. This file owns the part that is identical for every host:
// mapping the placed templates to their chest offsets, replaying the per-chunk
// post-process RNG for LootTableSeed, and evaluating the loot table.
namespace loots {
namespace {

AncientCityLayoutFn g_layout = nullptr;

int divFloor(int v, int d)
{
    int q = v / d;
    if (v < 0 && v % d) q--;
    return q;
}

const data::TemplateInfo *findTemplate(const std::string &name)
{
    for (const auto &t : data::kTemplateInfos)
        if (name == t.name) return &t;
    return nullptr;
}

int chestKind(const char *table)
{
    if (!table) return 0;
    if (std::strstr(table, "ancient_city_ice_box")) return 1;
    return 0;
}

} // namespace

void ancientCitySetLayoutProvider(AncientCityLayoutFn fn)
{
    g_layout = fn;
}

std::vector<CityChestInfo> ancientCityChests(int mc, uint64_t seed, uint32_t flags,
                                             const std::vector<std::pair<int, int>> &cities)
{
    (void)flags;
    std::vector<CityChestInfo> out;
    out.reserve(cities.size());
    for (const auto &city : cities) {
        CityChestInfo item{};
        item.x = city.first;
        item.z = city.second;
        item.chunkX = divFloor(city.first, 16);
        item.chunkZ = divFloor(city.second, 16);
        item.exists = false;
        item.pieces = 0;

        std::vector<AncientCityPiece> placed;
        if (!g_layout || !g_layout(mc, seed, city.first, city.second, placed) || placed.empty()) {
            out.push_back(std::move(item));
            continue;
        }

        item.exists = true;
        item.pieces = static_cast<int>(placed.size());

        // One post-process RNG per chunk, shared by every chest placed in that
        // chunk, exactly like vanilla's per-chunk decoration RNG.
        std::map<std::pair<int, int>, PostProcessRandom> postRngs;

        for (const auto &p : placed) {
            const data::TemplateInfo *layout = findTemplate(p.name);
            if (!layout) continue;

            const Rotation rot = rotationByIndex(p.rotation);
            const int sx = rot == Rotation::clockwise90 || rot == Rotation::counterclockwise90
                               ? layout->sz
                               : layout->sx;
            const int sz = rot == Rotation::clockwise90 || rot == Rotation::counterclockwise90
                               ? layout->sx
                               : layout->sz;
            item.bounds.minX = std::min(item.bounds.minX, p.x - 1);
            item.bounds.maxX = std::max(item.bounds.maxX, p.x + sx + 1);
            item.bounds.minZ = std::min(item.bounds.minZ, p.z - 1);
            item.bounds.maxZ = std::max(item.bounds.maxZ, p.z + sz + 1);
            item.bounds.minY = std::min(item.bounds.minY, p.y);
            item.bounds.maxY = std::max(item.bounds.maxY, p.y + layout->sy);

            for (int i = 0; i < layout->chestCount; i++) {
                const data::ChestSpec &spec = data::kChestSpecs[layout->firstChest + i];
                int tx, tz;
                templateTransform(spec.x, spec.z, Mirror::none, rot, 0, 0, tx, tz);

                CityChest chest{};
                chest.x = p.x + tx;
                chest.y = p.y + spec.y;
                chest.z = p.z + tz;
                chest.kind = chestKind(spec.table);

                const auto key = std::make_pair(chest.x >> 4, chest.z >> 4);
                auto it = postRngs.find(key);
                if (it == postRngs.end()) {
                    it = postRngs.emplace(
                        key, PostProcessRandom(
                                 mc, loots_structure_loot_seed(
                                         mc, seed, chest.x, chest.z, 13 /* Ancient_City */)))
                             .first;
                }
                chest.lootSeed = it->second.nextLong();

                const ChestReward reward =
                    evaluateChest(spec.table, chest.lootSeed, mc);
                if (!reward.evaluated) continue;
                chest.silence = reward.hasTrim(TrimKind::silence) ? 1 : 0;
                chest.ward = reward.hasTrim(TrimKind::ward) ? 1 : 0;
                chest.swiftSneakLevels = reward.swiftSneakLevels;
                chest.enchantedGoldenApples = reward.goldenApples;
                item.chests.push_back(std::move(chest));
            }
        }

        out.push_back(std::move(item));
    }
    return out;
}

} // namespace loots
